namespace EnterpriseDocumentIntelligence.IndexingService.Domain; public sealed record SearchIndexRecord(string Id,Guid DocumentId,string TenantId,string Content,IReadOnlyList<float> Vector,IReadOnlyCollection<string> AllowedPrincipals){public SearchIndexRecord{if(string.IsNullOrWhiteSpace(Id))throw new ArgumentException("Index id is required.");if(DocumentId==Guid.Empty)throw new ArgumentException("Document id is required.");if(string.IsNullOrWhiteSpace(TenantId))throw new ArgumentException("Tenant is required.");if(string.IsNullOrWhiteSpace(Content))throw new ArgumentException("Content is required.");if(Vector is null||Vector.Count==0)throw new ArgumentException("Vector is required.");}}